<script setup lang="ts">
import { reactive, ref, onMounted, computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import DataTable from './DataTable.vue'
import { api, lines } from './api'
const route=useRoute(),router=useRouter(),edit=Boolean(route.params.id),error=ref(''),busy=ref(false),loading=ref(edit),wordlist=ref('common'),selectedFile=ref<File|null>(null),savedWordlistCount=ref(0)
const commonSubdomains='www\nmail\nwebmail\napi\napp\nadmin\ndev\ntest\nstaging\nportal\nvpn\nftp\nsmtp\npop\nimap\nns1\nns2\nblog\nshop\ncdn\nstatic\nassets\nauth\nsso\nstatus\nsupport\ndocs\ngit\nci\nmonitor'
const form=reactive({mode:'network',domain:'',wordlist_filename:'',wordlist_import:null,subdomains:commonSubdomains,name:'',description:'',targets:'',ports:'',urls:'',credential_ids:[] as string[],password_spray:false,credential_endpoints:'',screenshots:false,request_timeout:2,max_threads:10,network_timing:3})
const count=computed(()=>lines(form.targets).reduce((n,t)=>{const parts=t.split('/');if(parts.length===1)return n+1;const bits=t.includes(':')?128:32;const prefix=Number(parts[1]);return n+(Number.isInteger(prefix)&&prefix>=0&&prefix<=bits?2**(bits-prefix):0)},0))
onMounted(async()=>{if(edit)try{const scan=await api(`/scans/${route.params.id}`);Object.assign(form,scan.config,{targets:scan.config.targets.join('\n'),urls:scan.config.urls.join('\n'),credential_endpoints:scan.config.credential_endpoints.join('\n'),subdomains:scan.config.wordlist_filename?'':(scan.config.subdomains||[]).join('\n')});savedWordlistCount.value=scan.config.subdomains?.length||0;wordlist.value=scan.config.wordlist_filename?'file':'custom'}catch(e){error.value=(e as Error).message}finally{loading.value=false}})
function chooseWordlist(){if(wordlist.value==='common')form.subdomains=commonSubdomains}
function importWordlist(event:Event){
  const input=event.target as HTMLInputElement,file=input.files?.[0]
  if(!file)return
  error.value=''
  if(file.size>3*1024*1024){error.value='Wordlist must be at most 3 MiB';input.value='';return}
  selectedFile.value=file
  wordlist.value='file'
  input.value=''
}
async function save(){
  busy.value=true;error.value=''
  try{
    const dns=form.mode==='subdomain'
    const fileMode=dns&&wordlist.value==='file'
    if(fileMode&&!selectedFile.value&&!form.wordlist_filename)throw new Error('Select a wordlist file')
    if(dns&&(!form.domain.trim()||(!fileMode&&!lines(form.subdomains).length)))throw new Error('Provide a base domain and a subdomain wordlist')
    if(!dns&&!lines(form.targets).length&&!lines(form.urls).length)throw new Error('Provide at least one IP/CIDR target or HTTP(S) URL')
    const body:Record<string,unknown>={...form,wordlist_filename:'',wordlist_import:null,domain:dns?form.domain:'',subdomains:dns?lines(form.subdomains):[],targets:dns?[]:lines(form.targets),urls:dns?[]:lines(form.urls),credential_endpoints:dns?[]:lines(form.credential_endpoints),credential_ids:dns?[]:form.credential_ids,password_spray:dns?false:form.password_spray,screenshots:dns?false:form.screenshots}
    if(fileMode){delete body.subdomains;delete body.wordlist_filename;delete body.wordlist_import}
    let payload:Record<string,unknown>|FormData=body
    if(fileMode&&selectedFile.value){
      payload=new FormData()
      payload.append('config',JSON.stringify(body))
      payload.append('wordlist',selectedFile.value)
    }
    const data=await api(edit?`/scans/${route.params.id}`:'/scans',edit?'PATCH':'POST',payload)
    await router.push(`/scans/${data.id}`)
  }catch(e){error.value=(e as Error).message}finally{busy.value=false}
}
function select(id:string,checked:boolean){form.credential_ids=checked?[...form.credential_ids,id]:form.credential_ids.filter(x=>x!==id)}
</script>
<template><div class="page-heading"><div><p class="eyebrow">SCAN CONFIGURATION</p><h1>{{edit?'Edit scan':'New scan'}}</h1><p class="muted">Changes apply to future runs. Existing run snapshots are preserved.</p></div><RouterLink class="button subtle" to="/scans">Back to scans</RouterLink></div><p v-if="loading" role="status">Loading configuration…</p><form v-else @submit.prevent="save" class="scan-form"><section class="panel"><h2>Scope & discovery</h2><label>Scan mode<select v-model="form.mode"><option value="network">Network</option><option value="subdomain">Subdomain</option></select></label><label>Scan name<input v-model="form.name" required maxlength="200" placeholder="Office network"></label><label>Description<textarea v-model="form.description" rows="2" maxlength="5000"/></label><template v-if="form.mode==='network'"><div class="form-grid"><label>Authorized IP addresses / CIDRs<textarea v-model="form.targets" rows="5" placeholder="192.0.2.10&#10;2001:db8::/126"/><small>Optional when URLs are provided. One entry per line. {{count.toLocaleString()}} explicit addresses; administrator limits apply.</small></label><div><label>TCP ports<input v-model="form.ports" placeholder="22,80,443,8000-8100"><small>Default: 1–1024. No UDP scanning in the MVP.</small></label></div></div><label>Explicit HTTP(S) URLs<textarea v-model="form.urls" rows="3" placeholder="https://service.example.test/"/><small>Provide URLs, IP targets, or both. With URLs only, IPs are resolved and fixed at launch. When IP targets are supplied, URL destinations must belong to that scope.</small></label></template><template v-else><label>Base domain<input v-model="form.domain" required maxlength="253" placeholder="example.com"><small>Gobuster will resolve each word as word.example.com using DNS.</small></label><label>Subdomain wordlist<select v-model="wordlist" @change="chooseWordlist"><option value="common">Common subdomains (30 entries)</option><option value="custom">Custom list</option><option value="file">Upload file</option></select></label><label v-if="wordlist==='file'">Import wordlist (.txt)<input type="file" accept=".txt,text/plain" @change="importWordlist"><small>One name per line: www, dev.api or a full subdomain of the base domain. Comments and invalid lines are skipped and reported. Maximum file size: 3 MiB. No limit on the number of names. The file is uploaded when you save the scan.</small></label><p v-if="wordlist==='file' && selectedFile" role="status">Selected: {{selectedFile.name}} ({{(selectedFile.size/1024).toFixed(1)}} KiB)</p><p v-else-if="wordlist==='file' && form.wordlist_filename" role="status">Saved wordlist: {{form.wordlist_filename}} · {{savedWordlistCount.toLocaleString()}} names</p><label v-if="wordlist!=='file'">Subdomains to test<textarea v-model="form.subdomains" @input="wordlist='custom'" required rows="10" placeholder="www&#10;api&#10;mail"/><small>{{lines(form.subdomains).length.toLocaleString()}} DNS candidates. Edit this list to choose exactly which names to test.</small></label><p class="muted">DNS enumeration with Gobuster. Results include discovered subdomains and their IP addresses.</p></template><h3>Timing & concurrency</h3><div class="form-grid"><label>Request timeout (seconds)<input v-model.number="form.request_timeout" type="number" min="0.001" max="300" step="0.001" required><small>{{form.mode==='subdomain'?'Timeout for each DNS lookup.':'TCP connection timeout for RustScan; maximum probe response timeout for Nmap.'}}</small></label><label>Maximum threads<input v-model.number="form.max_threads" type="number" min="1" max="1024" required><small>{{form.mode==='subdomain'?'Concurrent DNS workers in Gobuster.':'Concurrent RustScan connections and maximum parallel Nmap probes.'}}</small></label><label v-if="form.mode==='network'">Network timing<select v-model.number="form.network_timing"><option :value="0">T0 — Paranoid</option><option :value="1">T1 — Sneaky</option><option :value="2">T2 — Polite</option><option :value="3">T3 — Normal</option><option :value="4">T4 — Aggressive</option><option :value="5">T5 — Insane</option></select><small>Nmap timing profile. Higher values scan faster.</small></label></div><p class="muted">No total duration limit. The scan runs until completion or manual stop.</p></section><section v-if="form.mode==='network'" class="panel"><h2>Optional modules</h2><label class="check"><input v-model="form.screenshots" type="checkbox">Capture screenshots with EyeWitness</label><label class="check"><input v-model="form.password_spray" type="checkbox">Enable bounded credential validation</label><p class="muted">Both modules are off by default. Only HTTP Basic authentication is supported. Attempts use approved pairs, password first, with account and service budgets.</p><label v-if="form.password_spray">Explicitly approved credential endpoints<textarea v-model="form.credential_endpoints" rows="3" placeholder="https://service.example.test/protected" required/><small>Must also appear in the explicit URL list. Redirects are never followed for authentication.</small></label><h3>Approved credential library entries</h3><p>{{form.credential_ids.length}} selected (maximum 10)</p><DataTable endpoint="/credentials" query-key="credential-picker" :columns="[{key:'selected',label:'Select'},{key:'label',label:'Label'},{key:'username',label:'Username'}]"><template #selected="{row}"><input type="checkbox" :aria-label="`Select ${row.label}`" :checked="form.credential_ids.includes(row.id)" @change="select(row.id,($event.target as HTMLInputElement).checked)"></template></DataTable></section><p v-if="error" class="error" role="alert">{{error}}</p><div class="actions"><button :disabled="busy">{{busy?'Saving…':'Save scan'}}</button><RouterLink class="button subtle" to="/scans">Cancel</RouterLink></div></form></template>
